INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q1', 'GATE', 'CS', '', 2023, '1', 1, 'subj_CS_ga', '', '', 'MCQ', 1, 0, 'We reached the station late, and _______ missed the train.', ARRAY[ARRAY['near'], ARRAY['nearly'], ARRAY['utterly'], ARRAY['mostly']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
