INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q3', 'GATE', 'CS', '', 2023, '1', 3, 'subj_CS_ga', '', '', 'MCQ', 1, 0, 'A series of natural numbers 1, 2, 3, 4, 5, 6, 7, ... obeys +1 = + -1 for all integers 2 . If 6 = 37, and 7 = 60, then what is 1 ?', ARRAY[ARRAY['4'], ARRAY['5'], ARRAY['8'], ARRAY['9']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q4', 'GATE', 'CS', '', 2023, '1', 4, 'subj_CS_ga', '', '', 'MCQ', 1, 0, 'A survey for a certain year found that 90% of pregnant women received medical care at least once before giving birth. Of these women, 60% received medical care from doctors, while 40% received medical care from other healthcare providers. Given this information, which one of the following statements can be inferred with certainty?', ARRAY[ARRAY['More than half of the pregnant women received medical care at least once from a'], ARRAY['Less than half of the pregnant women received medical care at least once from a'], ARRAY['More than half of the pregnant women received medical care at most once from a'], ARRAY['Less than half of the pregnant women received medical care at most once from a']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q5', 'GATE', 'CS', '', 2023, '1', 5, 'subj_CS_ga', '', '', 'MCQ', 2, 0, 'Looking at the surface of a smooth 3-dimensional object from the outside, which one of the following options is TRUE?', ARRAY[ARRAY['The surface of the object must be concave everywhere.'], ARRAY['The surface of the object must be convex everywhere.'], ARRAY['The surface of the object may be concave in some places and convex in other places.'], ARRAY['The object can have edges, but no corners.']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q6', 'GATE', 'CS', '', 2023, '1', 6, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'The country of Zombieland is in distress since more than 75% of its working population is suffering from serious health issues. Studies conducted by competent health experts concluded that a complete lack of physical exercise among its working population was one of the leading causes of their health issues. As one of the measures to address the problem, the Government of Zombieland has decided to provide monetary incentives to those who ride bicycles to work. Based only on the information provided above, which one of the following statements can be logically inferred with certainty?', ARRAY[ARRAY['All the working population of Zombieland will henceforth ride bicycles to work.'], ARRAY['Riding bicycles will ensure that all of the working population of Zombieland is free'], ARRAY['The health experts suggested to the Government of Zombieland to declare riding'], ARRAY['The Government of Zombieland believes that riding bicycles is a form of physical']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q7', 'GATE', 'CS', '', 2023, '1', 7, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider two functions of time (), () = 0.01 2 () = 4 where 0 < < . Now consider the following two statements: (i) For some > 0, () > (). (ii) There exists a , such that () > () for all > . Which one of the following options is TRUE?', ARRAY[ARRAY['only (i) is correct'], ARRAY['only (ii) is correct'], ARRAY['both (i) and (ii) are correct'], ARRAY['neither (i) nor (ii) is correct']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q8', 'GATE', 'CS', '', 2023, '1', 8, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Which one of the following sentence sequences creates a coherent narrative? (i) Once on the terrace, on her way to her small room in the corner, she notices the man right away. (ii) She begins to pant by the time she has climbed all the stairs. (iii) Mina has bought vegetables and rice at the market, so her bags are heavy. (iv) He was leaning against the parapet, watching the traffic below.', ARRAY[ARRAY['(i), (ii), (iv), (iii)'], ARRAY['(ii), (iii), (i), (iv)'], ARRAY['(iv), (ii), (i), (iii)'], ARRAY['(iii), (ii), (i), (iv)']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q9', 'GATE', 'CS', '', 2023, '1', 9, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'f ( x) and g ( y) are functions of x and y, respectively, and f ( x) = g ( y) for all real values of and . Which one of the following options is necessarily TRUE for all x and y?', ARRAY[ARRAY['f ( x) = 0 and g ( y) = 0'], ARRAY['f ( x) = g ( y) = constant'], ARRAY['f ( x) constant and g ( y) constant'], ARRAY['f (x) + g ( y)= f (x) - g ( y)']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q10', 'GATE', 'CS', '', 2023, '1', 10, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Which one of the options best describes the transformation of the 2-dimensional figure P to Q, and then to R, as shown?', ARRAY[ARRAY['Operation 1: A clockwise rotation by 90� about an axis perpendicular to the plane'], ARRAY['Operation 1: A counter clockwise rotation by 90� about an axis perpendicular to'], ARRAY['Operation 1: A clockwise rotation by 90� about an axis perpendicular to the plane'], ARRAY['Operation 1: A counter clockwise rotation by 180� about an axis perpendicular to']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q11', 'GATE', 'CS', '', 2023, '1', 11, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the following statements regarding the front-end and back-end of a compiler. S1: The front-end includes phases that are independent of the target hardware. S2: The back-end includes phases that are specific to the target hardware. S3: The back-end includes phases that are specific to the programming language used in the source code. Identify the CORRECT option.', ARRAY[ARRAY['Only S1 is TRUE.'], ARRAY['Only S1 and S2 are TRUE.'], ARRAY['S1, S2, and S3 are all TRUE.'], ARRAY['Only S1 and S3 are TRUE.']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q12', 'GATE', 'CS', '', 2023, '1', 12, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Which one of the following sequences when stored in an array at locations A[1], . . . , A[10] forms a max-heap?', ARRAY[ARRAY['23, 17, 10, 6, 13, 14, 1, 5, 7, 12'], ARRAY['23, 17, 14, 7, 13, 10, 1, 5, 6, 12'], ARRAY['23, 17, 14, 6, 13, 10, 1, 5, 7, 15'], ARRAY['23, 14, 17, 1, 10, 13, 16, 12, 7, 5']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q13', 'GATE', 'CS', '', 2023, '1', 13, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Let SLLdel be a function that deletes a node in a singly-linked list given a pointer to the node and a pointer to the head of the list. Similarly, let DLLdel be another function that deletes a node in a doubly-linked list given a pointer to the node and a pointer to the head of the list. Let n denote the number of nodes in each of the linked lists. Which one of the following choices is TRUE about the worst-case time complexity of SLLdel and DLLdel?', ARRAY[ARRAY['SLLdel is O(1) and DLLdel is O(n)'], ARRAY['Both SLLdel and DLLdel are O(log(n))'], ARRAY['Both SLLdel and DLLdel are O(1)'], ARRAY['SLLdel is O(n) and DLLdel is O(1)']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q14', 'GATE', 'CS', '', 2023, '1', 14, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the Deterministic Finite-state Automaton (DFA) A shown below. The DFA runs on the alphabet {0, 1}, and has the set of states {s, p, q, r}, with s being the start state and p being the only final state. 0 1 s1 p q 1 0 r 0 0,1 Which one of the following regular expressions correctly describes the language accepted by A?', ARRAY[ARRAY['1(011)'], ARRAY['0(0 + 1)'], ARRAY['1(0 + 11)'], ARRAY['1(110)']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q15', 'GATE', 'CS', '', 2023, '1', 15, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'The Lucas sequence Ln is defined by the recurrence relation: Ln = Ln-1 + Ln-2, for n 3, with L1 = 1 and L2 = 3. Which one of the options given is TRUE? n n 1+ 5 1- 5', ARRAY[ARRAY['Ln = +'], ARRAY['Ln = - 3'], ARRAY['Ln = +'], ARRAY['Ln = - 2']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q16', 'GATE', 'CS', '', 2023, '1', 16, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Which one of the options given below refers to the degree (or arity) of a relation in relational database systems?', ARRAY[ARRAY['Number of attributes of its relation schema.'], ARRAY['Number of tuples stored in the relation.'], ARRAY['Number of entries in the relation.'], ARRAY['Number of distinct domains of its relation schema.']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q17', 'GATE', 'CS', '', 2023, '1', 17, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Suppose two hosts are connected by a point-to-point link and they are configured to use Stop-and-Wait protocol for reliable data transfer. Identify in which one of the following scenarios, the utilization of the link is the lowest.', ARRAY[ARRAY['Longer link length and lower transmission rate'], ARRAY['Longer link length and higher transmission rate'], ARRAY['Shorter link length and lower transmission rate'], ARRAY['Shorter link length and higher transmission rate']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q18', 'GATE', 'CS', '', 2023, '1', 18, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Let 1234 A = 43 1 2 23 4 1 2341 and 3412 B = 41 1 2 34 . 2 3 2341 Let det(A) and det(B) denote the determinants of the matrices A and B, respectively. Which one of the options given below is TRUE?', ARRAY[ARRAY['det(A) = det(B)'], ARRAY['det(B) = -det(A)'], ARRAY['det(A) = 0'], ARRAY['det(AB) = det(A) + det(B)']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q19', 'GATE', 'CS', '', 2023, '1', 19, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'Consider the following definition of a lexical token id for an identifier in a program- ming language, using extended regular expressions: letter [A-Za-z] digit [0-9] id letter (letter | digit) Which one of the following Non-deterministic Finite-state Automata with - transitions accepts the set of valid identifiers? (A double-circle denotes a final state) letter letter digit', NULL, NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q20', 'GATE', 'CS', '', 2023, '1', 20, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'An algorithm has to store several keys generated by an adversary in a hash table. The adversary is malicious who tries to maximize the number of collisions. Let k be the number of keys, m be the number of slots in the hash table, and k > m. Which one of the following is the best hashing strategy to counteract the adversary?', ARRAY[ARRAY['Division method, i.e., use the hash function h(k) = k mod m.'], ARRAY['Multiplication method, i.e., use the hash function h(k) = m(kA - kA ) , where'], ARRAY['Universal hashing method.'], ARRAY['If k is a prime number, use Division method. Otherwise, use Multiplication method.']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q21', 'GATE', 'CS', '', 2023, '1', 21, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'The output of a 2-input multiplexer is connected back to one of its inputs as shown in the figure. Multiplexer 0 Q 1 S Match the functional equivalence of this circuit to one of the following options.', ARRAY[ARRAY['D Flip-flop'], ARRAY['D Latch'], ARRAY['Half-adder'], ARRAY['Demultiplexer']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q22', 'GATE', 'CS', '', 2023, '1', 22, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Which one or more of the following need to be saved on a context switch from one thread (T1) of a process to another thread (T2) of the same process?', ARRAY[ARRAY['Page table base register'], ARRAY['Stack pointer'], ARRAY['Program counter'], ARRAY['General purpose registers']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q23', 'GATE', 'CS', '', 2023, '1', 23, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Which one or more of the following options guarantee that a computer system will transition from user mode to kernel mode?', ARRAY[ARRAY['Function Call'], ARRAY['malloc Call'], ARRAY['Page Fault'], ARRAY['System Call']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q24', 'GATE', 'CS', '', 2023, '1', 24, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Which of the following statements is/are CORRECT?', ARRAY[ARRAY['The intersection of two regular languages is regular.'], ARRAY['The intersection of two context-free languages is context-free.'], ARRAY['The intersection of two recursive languages is recursive.'], ARRAY['The intersection of two recursively enumerable languages is recursively enumerable.']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q25', 'GATE', 'CS', '', 2023, '1', 25, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Which of the following statements is/are INCORRECT about the OSPF (Open Shortest Path First) routing protocol used in the Internet?', ARRAY[ARRAY['OSPF implements Bellman-Ford algorithm to find shortest paths.'], ARRAY['OSPF uses Dijkstra''s shortest path algorithm to implement least-cost path routing.'], ARRAY['OSPF is used as an inter-domain routing protocol.'], ARRAY['OSPF implements hierarchical routing.']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q26', 'GATE', 'CS', '', 2023, '1', 26, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Geetha has a conjecture about integers, which is of the form x P (x) = yQ(x, y) , where P is a statement about integers, and Q is a statement about pairs of integers. Which of the following (one or more) option(s) would imply Geetha''s conjecture?', ARRAY[ARRAY['x P (x) yQ(x, y)'], ARRAY['xyQ(x, y)'], ARRAY['yx P (x) = Q(x, y)'], ARRAY['x P (x) yQ(x, y)']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q27', 'GATE', 'CS', '', 2023, '1', 27, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Which one or more of the following CPU scheduling algorithms can potentially cause starvation?', ARRAY[ARRAY['First-in First-Out'], ARRAY['Round Robin'], ARRAY['Priority Scheduling'], ARRAY['Shortest Job First']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q28', 'GATE', 'CS', '', 2023, '1', 28, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Let f (x) = x3 + 15x2 - 33x - 36 be a real-valued function. Which of the following statements is/are TRUE?', ARRAY[ARRAY['f (x) does not have a local maximum.'], ARRAY['f (x) has a local maximum.'], ARRAY['f (x) does not have a local minimum.'], ARRAY['f (x) has a local minimum.']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q29', 'GATE', 'CS', '', 2023, '1', 29, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Let f and g be functions of natural numbers given by f (n) = n and g(n) = n2. Which of the following statements is/are TRUE?', ARRAY[ARRAY['f O(g)'], ARRAY['f (g)'], ARRAY['f o(g)'], ARRAY['f (g)']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q30', 'GATE', 'CS', '', 2023, '1', 30, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'Let A be the adjacency matrix of the graph with vertices {1, 2, 3, 4, 5}. 3 5 21 4 Let 1, 2, 3, 4, and 5 be the five eigenvalues of A. Note that these eigenvalues need not be distinct. The value of 1 + 2 + 3 + 4 + 5 = . CS GATE 2023 Computer Science and Information Technology (CS)', NULL, NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q31', 'GATE', 'CS', '', 2023, '1', 31, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'The value of the definite integral 321 4x2y - z3 dz dy dx -3 -2 -1 is . (Rounded off to the nearest integer) CS GATE 2023 Computer Science and Information Technology (CS)', NULL, NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q32', 'GATE', 'CS', '', 2023, '1', 32, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'A particular number is written as 132 in radix-4 representation. The same number in radix-5 representation is . CS GATE 2023 Computer Science and Information Technology (CS)', NULL, NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q33', 'GATE', 'CS', '', 2023, '1', 33, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'Consider a 3-stage pipelined processor having a delay of 10 ns (nanoseconds), 20 ns, and 14 ns, for the first, second, and the third stages, respectively. Assume that there is no other delay and the processor does not suffer from any pipeline hazards. Also assume that one instruction is fetched every cycle. The total execution time for executing 100 instructions on this processor is ns. CS GATE 2023 Computer Science and Information Technology (CS)', NULL, NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q34', 'GATE', 'CS', '', 2023, '1', 34, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'A keyboard connected to a computer is used at a rate of 1 keystroke per second. The computer system polls the keyboard every 10 ms (milli seconds) to check for a keystroke and consumes 100 s (micro seconds) for each poll. If it is determined after polling that a key has been pressed, the system consumes an additional 200 s to process the keystroke. Let T1 denote the fraction of a second spent in polling and processing a keystroke. In an alternative implementation, the system uses interrupts instead of polling. An interrupt is raised for every keystroke. It takes a total of 1 ms for servicing an interrupt and processing a keystroke. Let T2 denote the fraction of a second spent in servicing the interrupt and processing a keystroke. The ratio T1 is . (Rounded off to one decimal place) T2 CS GATE 2023 Computer Science and Information Technology (CS)', NULL, NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q35', 'GATE', 'CS', '', 2023, '1', 35, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'The integer value printed by the ANSI-C program given below is . #include<stdio.h> int funcp(){ static int x = 1; x++; return x; } int main(){ int x,y; x = funcp(); y = funcp()+x; printf("%d\\n", (x+y)); return 0; } CS GATE 2023 Computer Science and Information Technology (CS) Q.36 � Q.65 Carry TWO mark each. CS GATE 2023 Computer Science and Information Technology (CS)', NULL, NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q36', 'GATE', 'CS', '', 2023, '1', 36, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the following program: int main() int f1() int f2(int X) int f3() { { { { f1(); return(1); f3(); return(5); f2(2); } if (X==1) } f3(); return f1(); return(0); else } return (X*f2(X-1)); } Which one of the following options represents the activation tree corresponding to the main function? main f1 f2 f3 f3 f2', ARRAY[ARRAY['f3 f1'], ARRAY['f3 f1'], ARRAY['f3 f1'], ARRAY['f3 f2 f1']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q37', 'GATE', 'CS', '', 2023, '1', 37, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the control flow graph shown. ENTRY B1 i=m-1 j=n a = 10 B2 i=i+1 j=j-1 B3 a = 20 B4 i=a+1 EXIT Which one of the following choices correctly lists the set of live variables at the exit point of each basic block?', ARRAY[ARRAY['B1: {}, B2: {a}, B3: {a}, B4: {a}'], ARRAY['B1: {i, j}, B2: {a}, B3: {a}, B4: {i}'], ARRAY['B1: {a, i, j}, B2: {a, i, j}, B3: {a, i}, B4: {a}'], ARRAY['B1: {a, i, j}, B2: {a, j}, B3: {a, j}, B4: {a, i, j}']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q38', 'GATE', 'CS', '', 2023, '1', 38, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the two functions incr and decr shown below. incr(){ decr(){ wait(s); wait(s); X = X+1; X = X-1; signal(s); signal(s); } } There are 5 threads each invoking incr once, and 3 threads each invoking decr once, on the same shared variable X. The initial value of X is 10. Suppose there are two implementations of the semaphore s, as follows: I-1: s is a binary semaphore initialized to 1. I-2: s is a counting semaphore initialized to 2. Let V1, V2 be the values of X at the end of execution of all the threads with implementations I-1, I-2, respectively. Which one of the following choices corresponds to the minimum possible values of V1, V2, respectively?', ARRAY[ARRAY['15, 7'], ARRAY['7, 7'], ARRAY['12, 7'], ARRAY['12, 8']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q39', 'GATE', 'CS', '', 2023, '1', 39, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the context-free grammar G below S aSb | X X aX | Xb | a | b , where S and X are non-terminals, and a and b are terminal symbols. The starting non-terminal is S. Which one of the following statements is CORRECT?', ARRAY[ARRAY['The language generated by G is (a + b)'], ARRAY['The language generated by G is a(a + b)b'], ARRAY['The language generated by G is ab(a + b)'], ARRAY['The language generated by G is not a regular language']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q40', 'GATE', 'CS', '', 2023, '1', 40, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the pushdown automaton (PDA) P below, which runs on the input alpha- bet {a, b}, has stack alphabet {, A}, and has three states {s, p, q}, with s being the start state. A transition from state u to state v, labelled c/X/, where c is an input symbol or , X is a stack symbol, and is a string of stack symbols, represents the fact that in state u, the PDA can read c from the input, with X on the top of its stack, pop X from the stack, push in the string on the stack, and go to state v. In the initial configuration, the stack has only the symbol in it. The PDA accepts by empty stack. a//A b/A/ a/A/AA s b/A/ p /A/ /A/ q /A/ // Which one of the following options correctly describes the language accepted by P ?', ARRAY[ARRAY['{ambn | 1 m and n < m}'], ARRAY['{ambn | 0 n m}'], ARRAY['{ambn | 0 m and 0 n}'], ARRAY['{am | 0 m} {bn | 0 n}']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q41', 'GATE', 'CS', '', 2023, '1', 41, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the given C-code and its corresponding assembly code, with a few operands U1�U4 being unknown. Some useful information as well as the semantics of each unique assembly instruction is annotated as inline comments in the code. The memory is byte-addressable. //C-code ;assembly-code (; indicates comments) ;r1-r5 are 32-bit integer registers ;initialize r1=0, r2=10 ;initialize r3, r4 with base address of a, b int a[10], b[10], i; L01: jeq r1, r2, end ;if(r1==r2) goto end // int is 32-bit L02: lw r5, 0(r4) ;r5 <- Memory[r4+0] for (i=0; i<10;i++) L03: shl r5, r5, U1 ;r5 <- r5 << U1 a[i] = b[i] * 8; L04: sw r5, 0(r3) ;Memory[r3+0] <- r5 L05: add r3, r3, U2 ;r3 <- r3+U2 L06: add r4, r4, U3 L07: add r1, r1, 1 L08: jmp U4 ;goto U4 L09: end Which one of the following options is a CORRECT replacement for operands in the position (U1, U2, U3, U4) in the above assembly code?', ARRAY[ARRAY['(8, 4, 1, L02)'], ARRAY['(3, 4, 4, L01)'], ARRAY['(8, 1, 1, L02)'], ARRAY['(3, 1, 1, L01)']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q42', 'GATE', 'CS', '', 2023, '1', 42, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'A 4 kilobyte (KB) byte-addressable memory is realized using four 1 KB memory blocks. Two input address lines (IA4 and IA3) are connected to the chip select (CS) port of these memory blocks through a decoder as shown in the figure. The remaining ten input address lines from IA11�IA0 are connected to the address port of these blocks. The chip select (CS) is active high. IA11 MSB IIAA190 IA8 10-bit IA7 IA6 1KB memory 1KB memory 1KB memory 1KB memory IA5 IA2 LSB IIAA10 Addr Addr Addr Addr Decoder X1 CS X2 CS X3 CS X4 CS IA4 Q0 IA3 AA01 Q1 Q2 Q3 The input memory addresses (IA11�IA0), in decimal, for the starting locations (Addr=0) of each block (indicated as X1, X2, X3, X4 in the figure) are among the options given below. Which one of the following options is CORRECT?', ARRAY[ARRAY['(0, 1, 2, 3)'], ARRAY['(0, 1024, 2048, 3072)'], ARRAY['(0, 8, 16, 24)'], ARRAY['(0, 0, 0, 0)']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q43', 'GATE', 'CS', '', 2023, '1', 43, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider a sequential digital circuit consisting of T flip-flops and D flip-flops as shown in the figure. CLKIN is the clock input to the circuit. At the beginning, Q1, Q2 and Q3 have values 0, 1 and 1, respectively. T D T CLKIN Q Q1 Q Q2 Q Q3 CLK CLK CLK Which one of the given values of (Q1, Q2, Q3) can NEVER be obtained with this digital circuit?', ARRAY[ARRAY['(0, 0, 1)'], ARRAY['(1, 0, 0)'], ARRAY['(1, 0, 1)'], ARRAY['(1, 1, 1)']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q44', 'GATE', 'CS', '', 2023, '1', 44, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'A Boolean digital circuit is composed using two 4-input multiplexers (M1 and M2) and one 2-input multiplexer (M3) as shown in the figure. X0�X7 are the inputs of the multiplexers M1 and M2 and could be connected to either 0 or 1. The select lines of the multiplexers are connected to Boolean variables A, B and C as shown. Multiplexer X0 0 M1 X1 1 Q X2 2 Multiplexer 0 X3 3 S1 S0 M3 Q A 1S C Multiplexer X4 0 X5 1 M2 Q X6 2 X7 3 S1 S0 A C B Which one of the following set of values of (X0, X1, X2, X3, X4, X5, X6, X7) will realise the Boolean function A + A.C + A.B.C?', ARRAY[ARRAY['(1, 1, 0, 0, 1, 1, 1, 0)'], ARRAY['(1, 1, 0, 0, 1, 1, 0, 1)'], ARRAY['(1, 1, 0, 1, 1, 1, 0, 0)'], ARRAY['(0, 0, 1, 1, 0, 1, 1, 1)']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q45', 'GATE', 'CS', '', 2023, '1', 45, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the IEEE-754 single precision floating point numbers P=0xC1800000 and Q=0x3F5C2EF4. Which one of the following corresponds to the product of these numbers (i.e., P � Q), represented in the IEEE-754 single precision format?', ARRAY[ARRAY['0x404C2EF4'], ARRAY['0x405C2EF4'], ARRAY['0xC15C2EF4'], ARRAY['0xC14C2EF4']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q46', 'GATE', 'CS', '', 2023, '1', 46, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Let A be a priority queue for maintaining a set of elements. Suppose A is implemented using a max-heap data structure. The operation Extract-Max(A) extracts and deletes the maximum element from A. The operation Insert(A,key) inserts a new element key in A. The properties of a max-heap are preserved at the end of each of these operations. When A contains n elements, which one of the following statements about the worst case running time of these two operations is TRUE?', ARRAY[ARRAY['Both Extract-Max(A) and Insert(A,key) run in O(1).'], ARRAY['Both Extract-Max(A) and Insert(A,key) run in O(log(n)).'], ARRAY['Extract-Max(A) runs in O(1) whereas Insert(A,key) runs in O(n).'], ARRAY['Extract-Max(A) runs in O(1) whereas Insert(A,key) runs in O(log(n)).']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q47', 'GATE', 'CS', '', 2023, '1', 47, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider the C function foo and the binary tree shown. typedef struct node { 10 int val; struct node *left, *right; 5 11 } node; int foo(node *p) { int retval; 3 8 13 if (p == NULL) return 0; else { retval = p->val + foo(p->left) + foo(p->right); printf("%d ", retval); return retval; } } When foo is called with a pointer to the root node of the given binary tree, what will it print?', ARRAY[ARRAY['3 8 5 13 11 10'], ARRAY['3 5 8 10 11 13'], ARRAY['3 8 16 13 24 50'], ARRAY['3 16 8 50 24 13']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q48', 'GATE', 'CS', '', 2023, '1', 48, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Let U = {1, 2, . . . , n}, where n is a large positive integer greater than 1000. Let k be a positive integer less than n. Let A, B be subsets of U with |A| = |B| = k and A B = . We say that a permutation of U separates A from B if one of the following is true. - All members of A appear in the permutation before any of the members of B. - All members of B appear in the permutation before any of the members of A. How many permutations of U separate A from B?', ARRAY[ARRAY['n!'], ARRAY['n (n - 2k)!'], ARRAY['n (n - 2k)! (k!)2'], ARRAY['2']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q49', 'GATE', 'CS', '', 2023, '1', 49, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Let f : A B be an onto (or surjective) function, where A and B are nonempty sets. Define an equivalence relation on the set A as a1 a2 if f (a1) = f (a2) , where a1, a2 A. Let E = {[x] : x A} be the set of all the equivalence classes under . Define a new mapping F : E B as F ([x]) = f (x), for all the equivalence classes [x] in E. Which of the following statements is/are TRUE?', ARRAY[ARRAY['F is NOT well-defined.'], ARRAY['F is an onto (or surjective) function.'], ARRAY['F is a one-to-one (or injective) function.'], ARRAY['F is a bijective function.']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q50', 'GATE', 'CS', '', 2023, '1', 50, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Suppose you are asked to design a new reliable byte-stream transport protocol like TCP. This protocol, named myTCP, runs over a 100 Mbps network with Round Trip Time of 150 milliseconds and the maximum segment lifetime of 2 minutes. Which of the following is/are valid lengths of the Sequence Number field in the myTCP header?', ARRAY[ARRAY['30 bits'], ARRAY['32 bits'], ARRAY['34 bits'], ARRAY['36 bits']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q51', 'GATE', 'CS', '', 2023, '1', 51, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Let X be a set and 2X denote the powerset of X. Define a binary operation on 2X as follows: AB = (A - B) (B - A) . Let H = (2X, ). Which of the following statements about H is/are correct?', ARRAY[ARRAY['H is a group.'], ARRAY['Every element in H has an inverse, but H is NOT a group.'], ARRAY['For every A 2X, the inverse of A is the complement of A.'], ARRAY['For every A 2X, the inverse of A is A.']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q52', 'GATE', 'CS', '', 2023, '1', 52, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Suppose in a web browser, you click on the www.gate-2023.in URL. The browser cache is empty. The IP address for this URL is not cached in your local host, so a DNS lookup is triggered (by the local DNS server deployed on your local host) over the 3-tier DNS hierarchy in an iterative mode. No resource records are cached anywhere across all DNS servers. Let RTT denote the round trip time between your local host and DNS servers in the DNS hierarchy. The round trip time between the local host and the web server hosting www.gate-2023.in is also equal to RTT. The HTML file associated with the URL is small enough to have negligible transmission time and negligible rendering time by your web browser, which references 10 equally small objects on the same web server. Which of the following statements is/are CORRECT about the minimum elapsed time between clicking on the URL and your browser fully rendering it?', ARRAY[ARRAY['7 RTTs, in case of non-persistent HTTP with 5 parallel TCP connections.'], ARRAY['5 RTTs, in case of persistent HTTP with pipelining.'], ARRAY['9 RTTs, in case of non-persistent HTTP with 5 parallel TCP connections.'], ARRAY['6 RTTs, in case of persistent HTTP with pipelining.']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q53', 'GATE', 'CS', '', 2023, '1', 53, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider a random experiment where two fair coins are tossed. Let A be the event that denotes HEAD on both the throws, B be the event that denotes HEAD on the first throw, and C be the event that denotes HEAD on the second throw. Which of the following statements is/are TRUE?', ARRAY[ARRAY['A and B are independent.'], ARRAY['A and C are independent.'], ARRAY['B and C are independent.'], ARRAY['Prob(B|C) = Prob(B)']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q54', 'GATE', 'CS', '', 2023, '1', 54, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Consider functions Function 1 and Function 2 expressed in pseudocode as follows: Function 1 Function 2 while n > 1 do for i = 1 to 100 n do for i = 1 to n do x = x + 1; x = x + 1; end for end for n = n/2 ; end while Let f1(n) and f2(n) denote the number of times the statement "x = x + 1" is executed in Function 1 and Function 2, respectively. Which of the following statements is/are TRUE?', ARRAY[ARRAY['f1(n) (f2(n))'], ARRAY['f1(n) o(f2(n))'], ARRAY['f1(n) (f2(n))'], ARRAY['f1(n) O(n)']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q55', 'GATE', 'CS', '', 2023, '1', 55, 'subj_CS_cs', '', '', 'MCQ', 2, 0, 'Let G be a simple, finite, undirected graph with vertex set {v1, . . . , vn}. Let (G) denote the maximum degree of G and let N = {1, 2, . . .} denote the set of all possible colors. Color the vertices of G using the following greedy strategy: for i = 1, . . . , n color(vi) min{j N : no neighbour of vi is colored j} Which of the following statements is/are TRUE?', ARRAY[ARRAY['This procedure results in a proper vertex coloring of G.'], ARRAY['The number of colors used is at most (G) + 1.'], ARRAY['The number of colors used is at most (G).'], ARRAY['The number of colors used is equal to the chromatic number of G.']]::text[], NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q56', 'GATE', 'CS', '', 2023, '1', 56, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'Let U = {1, 2, 3}. Let 2U denote the powerset of U . Consider an undirected graph G whose vertex set is 2U . For any A, B 2U , (A, B) is an edge in G if and only if (i) A = B, and (ii) either A B or B A. For any vertex A in G, the set of all possible orderings in which the vertices of G can be visited in a Breadth First Search (BFS) starting from A is denoted by B(A). If denotes the empty set, then the cardinality of B() is . CS GATE 2023 Computer Science and Information Technology (CS)', NULL, NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q57', 'GATE', 'CS', '', 2023, '1', 57, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'Consider the following two-dimensional array D in the C programming language, which is stored in row-major order: int D[128][128]; Demand paging is used for allocating memory and each physical page frame holds 512 elements of the array D. The Least Recently Used (LRU) page-replacement policy is used by the operating system. A total of 30 physical page frames are allocated to a process which executes the following code snippet: for (int i = 0; i < 128; i++) for (int j = 0; j < 128; j++) D[j][i] *= 10; The number of page faults generated during the execution of this code snippet is . CS GATE 2023 Computer Science and Information Technology (CS)', NULL, NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q58', 'GATE', 'CS', '', 2023, '1', 58, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'Consider a computer system with 57-bit virtual addressing using multi-level tree-structured page tables with L levels for virtual to physical address translation. The page size is 4 KB (1 KB = 1024 B) and a page table entry at any of the levels occupies 8 bytes. The value of L is . CS GATE 2023 Computer Science and Information Technology (CS)', NULL, NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q59', 'GATE', 'CS', '', 2023, '1', 59, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'Consider a sequence a of elements a0 = 1, a1 = 5, a2 = 7, a3 = 8, a4 = 9, and a5 = 2. The following operations are performed on a stack S and a queue Q, both of which are initially empty. I: push the elements of a from a0 to a5 in that order into S. II: enqueue the elements of a from a0 to a5 in that order into Q. III: pop an element from S. IV: dequeue an element from Q. V: pop an element from S. VI: dequeue an element from Q. VII: dequeue an element from Q and push the same element into S. VIII: Repeat operation VII three times. IX: pop an element from S. X: pop an element from S. The top element of S after executing the above operations is . CS GATE 2023 Computer Science and Information Technology (CS)', NULL, NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q60', 'GATE', 'CS', '', 2023, '1', 60, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'Consider the syntax directed translation given by the following grammar and se- mantic rules. Here N , I, F and B are non-terminals. N is the starting non-terminal, and #, 0 and 1 are lexical tokens corresponding to input letters "#", "0" and "1", respectively. X.val denotes the synthesized attribute (a numeric value) associated with a non-terminal X. I1 and F1 denote occurrences of I and F on the right hand side of a production, respectively. For the tokens 0 and 1, 0.val = 0 and 1.val = 1. N I # F N.val = I.val + F.val I I1 B I.val = (2 I1.val ) + B.val I B I.val = B.val F B F1 F.val = 1 (B.val + F1.val ) F B 2 B 0 F.val = 1 B .val 2 B.val = 0.val B 1 B.val = 1.val The value computed by the translation scheme for the input string 10#011 is . (Rounded off to three decimal places) CS GATE 2023 Computer Science and Information Technology (CS)', NULL, NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q61', 'GATE', 'CS', '', 2023, '1', 61, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'Consider the following table named Student in a relational database. The primary key of this table is rollNum. Student name gender marks rollNum Naman M 62 1 Aliya F 70 2 Aliya F 80 3 James M 82 4 Swati F 65 5 The SQL query below is executed on this database. SELECT * FROM Student WHERE gender = `F'' AND marks > 65; The number of rows returned by the query is . CS GATE 2023 Computer Science and Information Technology (CS)', NULL, NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q62', 'GATE', 'CS', '', 2023, '1', 62, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'Consider a database of fixed-length records, stored as an ordered file. The database has 25,000 records, with each record being 100 bytes, of which the primary key occupies 15 bytes. The data file is block-aligned in that each data record is fully contained within a block. The database is indexed by a primary index file, which is also stored as a block-aligned ordered file. The figure below depicts this indexing scheme. Data File Primary Key Other Fields (15 Bytes) (85 Bytes) Index File Block Anchor Block Primary Key Pointer Suppose the block size of the file system is 1024 bytes, and a pointer to a block occupies 5 bytes. The system uses binary search on the index file to search for a record with a given key. You may assume that a binary search on an index file of b blocks takes log2 b block accesses in the worst case. Given a key, the number of block accesses required to identify the block in the data file that may contain a record with the key, in the worst case, is . CS GATE 2023 Computer Science and Information Technology (CS) CS GATE 2023 Computer Science and Information Technology (CS)', NULL, NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q63', 'GATE', 'CS', '', 2023, '1', 63, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'Consider the language L over the alphabet {0, 1}, given below: L = {w {0, 1} | w does not contain three or more consecutive 1''s}. The minimum number of states in a Deterministic Finite-State Automaton (DFA) for L is . CS GATE 2023 Computer Science and Information Technology (CS)', NULL, NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q64', 'GATE', 'CS', '', 2023, '1', 64, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'An 8-way set associative cache of size 64 KB (1 KB = 1024 bytes) is used in a system with 32-bit address. The address is sub-divided into TAG, INDEX, and BLOCK OFFSET. The number of bits in the TAG is . CS GATE 2023 Computer Science and Information Technology (CS)', NULL, NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);
INSERT INTO pyq_questions (id, exam, branch_code, branch_name, year, session, question_number, subject_id, topic, subtopic, question_type, marks, negative_marks, question_text, options, correct_answer, difficulty, source_name, source_url, source_type, source_year, retrieved_at) VALUES ('gate_cs_2023_s1_q65', 'GATE', 'CS', '', 2023, '1', 65, 'subj_CS_cs', '', '', 'NAT', 2, 0, 'The forwarding table of a router is shown below. Subnet Number Subnet Mask Interface ID 200.150.0.0 255.255.0.0 1 200.150.64.0 255.255.224.0 2 200.150.68.0 255.255.255.0 3 200.150.68.64 255.255.255.224 4 Default 0 A packet addressed to a destination address 200.150.68.118 arrives at the router. It will be forwarded to the interface with ID . CS', NULL, NULL, 2, 'GATE Official 2023 Question Paper', 'https://gate2026.iitg.ac.in/doc/download/2023/', 'official', 2023, NOW()) ON CONFLICT (id) DO UPDATE SET question_text = EXCLUDED.question_text, correct_answer = COALESCE(EXCLUDED.correct_answer, pyq_questions.correct_answer);